referenceSolutions.javascript:
export function solve(left, right) {
  const rows = new Map();
  for (const row of [...left, ...right]) rows.set(row.id, { ...(rows.get(row.id) ?? {}), ...row });
  return [...rows.values()].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
}

